import{_ as t,o as a,c as o,a3 as s}from"./chunks/framework.DAK02U1-.js";const m=JSON.parse('{"title":"Build Profiling","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Build Profiling | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/catter/features/build-profiling"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/catter/features/build-profiling"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/catter/features/build-profiling"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/catter/features/build-profiling"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/catter/features/build-profiling"}]]},"headers":[],"relativePath":"catter/features/build-profiling.md","filePath":"en/catter/features/build-profiling.md","lastUpdated":1793214814000}'),n={name:"catter/features/build-profiling.md"};function r(i,e,d,c,h,l){return a(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="build-profiling" tabindex="-1">Build Profiling <a class="header-anchor" href="#build-profiling" aria-label="Permalink to &quot;Build Profiling&quot;">​</a></h1><p><code>profile</code> records when each command of the build started, how long it ran and which command started it, and writes them as a trace that <a href="https://ui.perfetto.dev" target="_blank" rel="noreferrer">Perfetto</a> and <code>chrome://tracing</code> open: the build&#39;s timeline, with how many of its commands ran at once, the chain of steps that set its length, and the steps that took the longest.</p><p>Command: <code>profile</code></p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">catter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> profile</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [options] -- </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">build-command</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><h2 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td><code>-o, --output &lt;path&gt;</code></td><td>Write the trace to this path; a relative one is from the <code>-C</code> directory. Default: <code>trace.json</code>.</td></tr><tr><td><code>--top &lt;n&gt;</code></td><td>List the n commands that took the longest. Default: 5; <code>0</code> lists none.</td></tr><tr><td><code>-q, --quiet</code></td><td>Print no summary, nor why catter could not capture a command.</td></tr></tbody></table><p><code>profile</code> also takes the options of every command that runs a build: <code>-C</code>, <code>--capture</code>, <code>--from</code> and the handlers&#39; (see <a href="./../guide/configuration">Configuration</a>).</p><p>catter writes the trace once the build has ended, whether it succeeded or failed, making the directory it goes in when there is none, and exits as the build did. When it cannot write the trace, it says why and exits with 1; a build a handler aborts gets no trace. Unless <code>-q</code> is given, catter prints why it could not capture a command as it hears of it.</p><h2 id="the-trace" tabindex="-1">The trace <a class="header-anchor" href="#the-trace" aria-label="Permalink to &quot;The trace&quot;">​</a></h2><p>The trace is a JSON file in Chrome&#39;s trace event format. Open it in <a href="https://ui.perfetto.dev" target="_blank" rel="noreferrer">ui.perfetto.dev</a> (Open trace file), or in <code>chrome://tracing</code> (Load). Its times are in microseconds from when the first command started.</p><ul><li><strong>Lanes.</strong> Each command is a slice on a lane. A command runs within the command that started it, on its lane, when it starts and ends while that command runs and the commands that command started never ran two at once: a shell and the compiler it runs, a compiler driver and its stages (<code>cc1plus</code>, <code>as</code>, <code>collect2</code>, <code>ld</code>). The commands a build tool runs at once each go on the first lane where nothing runs as they start: under <code>make -j8</code>, lane 1 holds <code>make</code>, and the lanes below it its jobs, as many as ran at once.</li><li><strong>critical path.</strong> A track above the lanes holds the commands of the critical path (see below).</li><li><strong>running.</strong> A counter of how many commands work at each moment. A command works while it runs and no command it started does; a compiler or archiver command catter analyzes works for as long as it runs, together with the programs it starts.</li></ul><p>Each slice is named by its program and, for a command catter analyzes, the file it is about: the source a compile compiles (<code>c++ main.cc</code>), the file a link or an archive makes (<code>c++ app</code>, <code>ar libfoo.a</code>). Its category is what the command does, for one catter analyzes: <code>compile</code>, <code>link</code>, <code>preprocess</code>, <code>archive</code>, ... Its arguments hold:</p><table tabindex="0"><thead><tr><th>Argument</th><th>Holds</th></tr></thead><tbody><tr><td><code>command</code></td><td>Its arguments, on one line: each as it is when it holds only ASCII letters, digits and <code>_@%+=:,./\\-</code>, else as a JSON string.</td></tr><tr><td><code>cwd</code></td><td>The directory it ran in.</td></tr><tr><td><code>exit</code></td><td>Its exit code; 128 and the signal&#39;s number for one a signal ended.</td></tr><tr><td><code>id</code></td><td>Its id in the session, which <code>parent</code> names.</td></tr><tr><td><code>parent</code></td><td>The id of the command that started it; none for the build command.</td></tr><tr><td><code>writes</code></td><td>For a command catter analyzes, the files it writes.</td></tr><tr><td><code>target</code></td><td>For a compile, the files the commands that read its object write: the library or the program the object goes into.</td></tr></tbody></table><h2 id="the-summary" tabindex="-1">The summary <a class="header-anchor" href="#the-summary" aria-label="Permalink to &quot;The summary&quot;">​</a></h2><p>Unless <code>-q</code> is given, catter prints what the trace shows once it has written it:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Profiled 1234 commands in 83.4 s: 6.2 ran at once on average, 16 at most.</span></span>
<span class="line"><span>Critical path, 48.9 s: c++ big.cc 41.0 s &gt; ar libcore.a 400 ms &gt; c++ app 7.5 s</span></span>
<span class="line"><span>Slowest:</span></span>
<span class="line"><span>  41.0 s  c++ big.cc</span></span>
<span class="line"><span>   7.5 s  c++ app</span></span>
<span class="line"><span>   3.1 s  python3</span></span>
<span class="line"><span>   2.9 s  c++ parser.cc</span></span>
<span class="line"><span>   2.0 s  cmake</span></span>
<span class="line"><span>Trace saved to /src/project/trace.json: open it in https://ui.perfetto.dev or chrome://tracing.</span></span></code></pre></div><ul><li><strong>The first line</strong> says how long the build took, from the first command&#39;s start to the last one&#39;s end; how many commands worked at once on average, the time they worked, added up, over how long the build took; and the most that worked at once.</li><li><strong>The critical path</strong> is the chain of compiles, archives and links, each reading a file the one before it wrote, whose steps took the longest, added up. The files it follows are those a compiler&#39;s or an archiver&#39;s arguments name: a program catter does not analyze, as a code generator, and the headers a compile includes are not in it, so the chain can be shorter than the one that set the build&#39;s length. A path of more than six steps shows its first three and last two.</li><li><strong>The slowest</strong> commands are those that worked the longest. A build tool, a shell or a script is counted only for the time it worked itself: <code>make</code> reading its makefiles, <code>cmake</code> configuring, but not the compiles they wait for.</li><li>When commands are left out of the trace, a line says how many: those catter could not capture, and those that did not end before the build did, as a build server that outlives it.</li></ul><h2 id="times-and-capture-backends" tabindex="-1">Times and capture backends <a class="header-anchor" href="#times-and-capture-backends" aria-label="Permalink to &quot;Times and capture backends&quot;">​</a></h2><p>Every capture backend gives each command&#39;s start and duration:</p><table tabindex="0"><thead><tr><th>Backend</th><th>Start and duration</th></tr></thead><tbody><tr><td><code>hook</code></td><td>On Linux and macOS, <code>catter-proxy</code> measures each command, from when it starts the program catter told it to run to the program&#39;s exit; on Windows, catter does, from when it takes over the program the hook started, suspended, to its exit. Each program of the build waits for catter&#39;s decision before it starts, and on Linux and macOS starts through <code>catter-proxy</code>: the trace shows the build as it runs under catter.</td></tr><tr><td><code>wrapper</code></td><td>As under <code>hook</code>, for the compilers, linkers and archivers the shims stand for, and the build command: the trace holds only those.</td></tr><tr><td><code>ptrace</code></td><td>The times catter&#39;s tracer sees each process exec its program and exit. Each process of the build stops at each fork, exec and exit while catter reads it.</td></tr><tr><td><code>eslogger</code></td><td>The times Endpoint Security gives each exec and exit. It only observes: the build runs as it would without catter.</td></tr><tr><td><code>--from</code></td><td>The times the file records, in microseconds: an event&#39;s <code>execution</code> holds its <code>start</code>, since the session started, and its <code>duration</code>. A time it does not record is <code>0</code>.</td></tr></tbody></table><h2 id="use-cases" tabindex="-1">Use Cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use Cases&quot;">​</a></h2><ul><li><strong>Identify serialization bottlenecks</strong> -- Find stages where the build runs one command at a time despite available cores: the <code>running</code> counter drops to one.</li><li><strong>Measure actual parallelism</strong> -- Compare how many commands ran at once with the number of cores, and with the <code>-j</code> the build tool was given.</li><li><strong>Find slow compilation units</strong> -- Pinpoint the sources that take disproportionately long to compile, and those on the critical path.</li><li><strong>Debug build system configuration</strong> -- Detect misconfigured dependencies, unnecessary serialization, or suboptimal job scheduling.</li></ul>`,23)])])}const u=t(n,[["render",r]]);export{m as __pageData,u as default};
